const effectiveRulesFor=(node:CanonicalPropertyNode,recipe:ProfileInheritanceRecipe):CanonicalRule[]=>node.rules.flatMap((rule)=>{if(rule.enforcement==="invariant")return[clone(rule)];const replacements=recipe.ruleReplacements.filter(({sourceRuleId,propertyId})=>sourceRuleId===rule.id&&propertyId===node.id);if(replacements.length)return replacements.map(({rule:replacement})=>clone(replacement));return recipe.excludedRuleIds.includes(rule.id)?[]:[clone(rule)];});
