const sourceDefinitionFingerprints=(document:CanonicalSchemaDocument,selection:ProfileInheritanceSelection):Record<string,string>=>Object.fromEntries(Object.entries(sourceDefinitionValues(document,selection)).map(([id,value])=>[id,definitionDigest(value)]));
export function profileInheritanceSourceSnapshot(document:CanonicalSchemaDocument,recipe:ProfileInheritanceRecipe):ProfileInheritanceSourceSnapshot{const selection=profileInheritanceSelection(document,recipe),ruleBearingPropertyIds=stableUnique([...selection.directPropertyIds,...selection.ruleDependencyPropertyIds]);return{revision:document.revision,effectivePropertyIds:[...selection.effectivePropertyIds],propertyPaths:Object.fromEntries(selection.effectivePropertyIds.flatMap((propertyId)=>document.nodes[propertyId]?[[propertyId,canonicalPropertyPath(document,propertyId)]]:[])),ruleFingerprints:sourceRuleFingerprints(document,ruleBearingPropertyIds),definitionFingerprints:sourceDefinitionFingerprints(document,selection),missingRuleDependencyKeys:selection.missingRuleDependencies.map(missingDependencyKey)};}
