export function markProfileInheritanceTargetStale<T extends Record<string,unknown>>(target:T,profileId:string,before:CanonicalSchemaDocument,after:CanonicalSchemaDocument):T{const recipes=((target.profileInheritanceRecipes as ProfileInheritanceRecipe[]|undefined)??[]),affected=recipes.some((recipe)=>recipe.profileId===profileId);if(!affected)return target;const nextRecipes=recipes.map((recipe)=>{if(recipe.profileId!==profileId)return recipe;const impact=recipe.sourceSnapshot?profileInheritanceCurrentImpact(after,recipe):profileInheritanceImpact(before,after,recipe);return{...clone(recipe),sourceImpact:impact};}),stale=nextRecipes.some((recipe)=>recipe.profileId===profileId&&recipe.sourceImpact?.stale);return{...target,profileInheritanceRecipes:nextRecipes,...(stale?{compiledTargetsStale:true,validationStale:true,testCasesStale:true,documentationStale:true,exportStale:true}:{})};}
export function markProfileInheritanceConsumersForSourceChange(project:ProjectState["project"],profileId:string,before:CanonicalSchemaDocument,after:CanonicalSchemaDocument):ProjectState["project"]{return{...project,collections:{...project.collections,pages:project.collections.pages.map((entity)=>markProfileInheritanceTargetStale(entity,profileId,before,after)),pageGroups:project.collections.pageGroups.map((entity)=>markProfileInheritanceTargetStale(entity,profileId,before,after)),events:project.collections.events.map((entity)=>markProfileInheritanceTargetStale(entity,profileId,before,after))}};}
